        "code": "from datetime import date as calendar_date\nimport pandas as pd\n\ndef daily_report(events, start, end):\n    def is_iso_day(value):\n        if not isinstance(value, str):\n            return False\n        try:\n            return calendar_date.fromisoformat(value).isoformat() == value\n        except ValueError:\n            return False\n\n    df = pd.DataFrame(events, columns=['event_id', 'date', 'amount', 'revision'], dtype=object)\n    if df['event_id'].isna().any() or df['event_id'].astype('string').str.strip().eq('').any():\n        raise ValueError('event_id должен быть непустым')\n    for name in ['amount', 'revision']:\n        if df[name].isna().any() or df[name].lt(0).any():\n            raise ValueError(name + ' должен быть известным и неотрицательным')\n    if not df['date'].map(is_iso_day).all():\n        raise ValueError('Дата должна быть корректной строкой YYYY-MM-DD')\n    df['date'] = pd.to_datetime(df['date'], format='%Y-%m-%d', errors='raise')\n    calendar = pd.date_range(start, end, freq='D')\n    current = df.loc[df['date'].between(calendar[0], calendar[-1])]\n    latest = current.sort_values('revision', kind='stable').drop_duplicates('event_id', keep='first')\n    current = latest\n    daily = current.set_index('date')['amount'].resample('D').sum()\n    complete = daily.reindex(daily.index, fill_value=0)\n    return [{'day': day.date().isoformat(), 'amount': int(value)}\n            for day, value in complete.items()]",
