          "append": "import contextlib as _contextlib,json as _json,threading as _threading\nfrom http.server import BaseHTTPRequestHandler as _Handler,ThreadingHTTPServer as _HTTPServer\nfrom urllib.parse import urlsplit as _urlsplit,parse_qs as _parse_qs\nimport requests as _requests\n@_contextlib.contextmanager\ndef _api(routes=None):\n    _routes=dict(routes or {});_received=[]\n    class Handler(_Handler):\n        def log_message(self,*args):pass\n        def respond(self):\n            path=_urlsplit(self.path);query=_parse_qs(path.query,keep_blank_values=True)\n            length=int(self.headers.get('Content-Length','0'))\n            raw=self.rfile.read(length) if length else b''\n            _received.append((self.command,path.path,query,raw,dict(self.headers)))\n            if path.path=='/query':status,kind,body=200,'application/json',{'query':query}\n            elif path.path=='/echo':status,kind,body=201,'application/json',{'received':_json.loads(raw),'content_type':self.headers.get('Content-Type')}\n            else:status,kind,body=_routes.get(self.path,_routes.get(path.path,(404,'application/json',{'error':'missing'})))\n            data=body if isinstance(body,bytes) else _json.dumps(body,ensure_ascii=False).encode('utf-8')\n            self.send_response(status)\n            if kind:self.send_header('Content-Type',kind)\n            if status in (301,302,303,307,308):self.send_header('Location',body.decode() if isinstance(body,bytes) else str(body))\n            self.send_header('Content-Length',str(len(data)));self.end_headers()\n            try:self.wfile.write(data)\n            except (BrokenPipeError,ConnectionResetError):pass\n        do_GET=do_POST=respond\n    class Session(_requests.Session):\n        def __init__(self):\n            super().__init__();self.trust_env=False;self.calls=[];self.responses=[]\n        def request(self,method,url,**kwargs):\n            self.calls.append((method.upper(),url,kwargs))\n            response=super().request(method,url,**kwargs);self.responses.append(response)\n            original=response.iter_content\n            response._course_bytes=0\n            def observed(*args,**kw):\n                for piece in original(*args,**kw):\n                    response._course_bytes+=len(piece)\n                    yield piece\n            response.iter_content=observed\n            return response\n    server=_HTTPServer(('127.0.0.1',0),Handler)\n    thread=_threading.Thread(target=server.serve_forever,kwargs={'poll_interval':.01},daemon=True);thread.start()\n    session=Session();base='http://127.0.0.1:'+str(server.server_port)\n    try:yield session,base,_received\n    finally:\n        session.close();server.shutdown();server.server_close();thread.join(1)\ndef _timeouts(session):\n    assert session.calls and all(call[2].get('timeout')==(1,2) and call[2].get('allow_redirects') is False for call in session.calls), 'Передайте timeout=(1,2) и allow_redirects=False в каждый запрос'\ndef _bounds(session):\n    assert all(call[2].get('stream') is True for call in session.calls), 'Читайте ответ потоково'\n    assert all(response._content is False and response._course_bytes<=9216 and response.raw.closed for response in session.responses), 'Ограничьте чтение 8192 байт + один chunk до 1024 и закройте ответ'\n\nwith _api({'/ok':(200,'application/json',{'count':0,'label':'учебный'}),'/bad':(404,'application/json',{'error':'missing'}),'/invalid':(200,'application/json',b'not json')}) as (s,base,received):\n    assert read_json(s,base+'/ok')=={'count':0,'label':'учебный'}\n    try:read_json(s,base+'/bad')\n    except _requests.HTTPError as error:assert error.response.status_code==404\n    else:raise AssertionError('404 нельзя принять как успешные данные')\n    try:read_json(s,base+'/invalid')\n    except ValueError:pass\n    else:raise AssertionError('Неверный JSON должен дать ошибку')\n    _timeouts(s);assert len(received)==3\nprint('OK')",
