        "answer": "def _bounded_json(session,url):\n    import json,requests\n    with session.get(url,timeout=(1,2),allow_redirects=False,stream=True) as response:\n        response.raise_for_status()\n        if response.status_code!=200:raise requests.HTTPError('Expected 200 without redirect',response=response)\n        if response.headers.get('Content-Type','').split(';',1)[0].strip().lower()!='application/json':raise ValueError('Expected JSON content type')\n        parts=[];size=0\n        for piece in response.iter_content(chunk_size=1024):\n            size+=len(piece)\n            if size>8192:raise ValueError('Response exceeds 8192 bytes')\n            parts.append(piece)\n        return json.loads(b''.join(parts))\ndef _same_origin(url,base):\n    from urllib.parse import urljoin,urlsplit\n    if not isinstance(url,str) or not url.strip() or any(ord(c)<=32 or ord(c)==127 for c in url.strip()):raise ValueError('Invalid URL')\n    target=urlsplit(urljoin(base,url.strip()));origin=urlsplit(base)\n    if target.scheme not in ('http','https') or not target.hostname or target.username is not None or target.password is not None:raise ValueError('Invalid target')\n    def key(parts):return parts.scheme,parts.hostname,parts.port if parts.port is not None else (443 if parts.scheme=='https' else 80)\n    if key(target)!=key(origin):raise ValueError('Different origin')\n    return target._replace(fragment='').geturl()\ndef fetch_catalog(session,url):\n    result=[];seen_sku=set();seen_urls=set();current=_same_origin(url,url)\n    for page in range(3):\n        if current in seen_urls:raise ValueError('Pagination cycle')\n        seen_urls.add(current)\n        data=_bounded_json(session,current)\n        if type(data) is not dict or set(data)!={'items','next'} or type(data['items']) is not list:raise ValueError('Invalid page')\n        for item in data['items']:\n            if type(item) is not dict or set(item)!={'sku','qty'} or not isinstance(item['sku'],str) or not 1<=len(item['sku'].strip())<=40 or type(item['qty']) is not int or not 0<=item['qty']<=10000:raise ValueError('Invalid item')\n            sku=item['sku'].strip()\n            if sku not in seen_sku:result.append({'sku':sku,'qty':item['qty']});seen_sku.add(sku)\n        if data['next'] is None:return result\n        current=_same_origin(data['next'],current)\n    raise ValueError('More than three pages')",
