        "code": "def inspect_snapshot(path):\n    pass",
        "codeLang": "python",
        "answer": "import os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom contextlib import closing\n\ndef inspect_snapshot(path):\n    path=Path(path).resolve(strict=True)\n    if not path.is_file():raise ValueError('Нужен файл')\n    with closing(sqlite3.connect(path.as_uri()+'?mode=ro',uri=True,timeout=0)) as con:\n        if con.execute('PRAGMA integrity_check').fetchall()!=[('ok',)]:\n            raise ValueError('Повреждённая БД')\n        tables={r[0] for r in con.execute(\"SELECT name FROM sqlite_schema WHERE type='table'\")}\n        if not {'notes','meta'}<=tables:raise ValueError('Не учебный снимок')\n        if {r[1] for r in con.execute('PRAGMA table_info(notes)')}!={'id','title','done','version'}:\n            raise ValueError('Неизвестная схема notes')\n        if {r[1] for r in con.execute('PRAGMA table_info(meta)')}!={'revision'}:\n            raise ValueError('Неизвестная схема meta')\n        revisions=con.execute('SELECT revision FROM meta').fetchall()\n        if len(revisions)!=1 or type(revisions[0][0]) is not int or revisions[0][0]<0:\n            raise ValueError('Неверная ревизия')\n        rows=con.execute('SELECT id,title,done,version FROM notes ORDER BY id').fetchall()\n        for id,title,done,version in rows:\n            if type(id) is not int or type(title) is not str or type(done) is not int or done not in (0,1) or type(version) is not int or version<=0:\n                raise ValueError('Неверные данные notes')\n        return {'revision':revisions[0][0],'total':len(rows),'done':sum(r[2] for r in rows)}",
