          "append": "import os\nimport sqlite3\nimport time\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom contextlib import closing\n\ndef _seed(path,revision=0,rows=()):\n    with closing(sqlite3.connect(path)) as con:\n        con.execute('CREATE TABLE meta(revision INTEGER)')\n        con.execute('CREATE TABLE notes(id INTEGER PRIMARY KEY,title TEXT,done INTEGER,version INTEGER)')\n        con.execute('INSERT INTO meta VALUES (?)',(revision,))\n        con.executemany('INSERT INTO notes VALUES (?,?,?,?)',rows)\n        con.commit()\ndef _rows(path):\n    with closing(sqlite3.connect(Path(path).resolve().as_uri()+'?mode=ro',uri=True)) as con:\n        return con.execute('SELECT id,title,done,version FROM notes ORDER BY id').fetchall()\ndef _raises(types,fn,*args):\n    try:fn(*args)\n    except types:return\n    raise AssertionError('Нужен отказ, не видимость успеха')\n\nwith TemporaryDirectory() as folder:\n    root=Path(folder);low=root/'low.db';latest=root/'latest.db';tie=root/'same-revision.db'\n    _seed(low,4,[(0,'older',1,99)]);_seed(latest,8);_seed(tie,8,[(7,'tie must lose',0,1)])\n    os.utime(low,(2000000000,2000000000));os.utime(latest,(1000000000,1000000000))\n    bad=root/'bad.db';_seed(bad,99,[(0,'invalid',2,1)])\n    corrupt=root/'corrupt';corrupt.write_bytes(b'not sqlite')\n    missing=root/'missing.db';dest=root/'restored.db'\n    before={p:p.read_bytes() for p in (low,latest,tie,bad,corrupt)}\n    assert recover_latest([missing,corrupt,bad,low,latest,tie],dest)=={'revision':8,'total':0,'done':0}\n    assert _rows(dest)==[] and not missing.exists()\n    assert all(p.read_bytes()==value for p,value in before.items())\n    with closing(sqlite3.connect(dest)) as con:\n        con.execute(\"INSERT INTO notes VALUES (1,'restored edit',0,1)\");con.commit()\n    assert _rows(latest)==[]\n    _raises(FileExistsError,recover_latest,[low],dest);assert _rows(dest)==[(1,'restored edit',0,1)]\n    _raises(ValueError,recover_latest,[],root/'none.db');assert not (root/'none.db').exists()\n    _raises(ValueError,recover_latest,[missing,bad,corrupt],root/'none.db');assert not (root/'none.db').exists()\n    _raises(FileExistsError,recover_latest,[low],low);assert low.read_bytes()==before[low]\n    zero=root/'zero.db';_seed(zero,0)\n    assert recover_latest([zero],root/'zero-restored.db')=={'revision':0,'total':0,'done':0}\n    with closing(sqlite3.connect(latest)) as locked:\n        locked.execute('BEGIN EXCLUSIVE')\n        _raises(sqlite3.OperationalError,recover_latest,[low,latest],root/'must-not-fallback.db')\n        assert not (root/'must-not-fallback.db').exists();locked.rollback()\n    original=sqlite3.connect;raced=root/'race.db'\n    class DuringBackup(sqlite3.Connection):\n        def backup(self,target,*args,**kwargs):\n            raced.write_bytes(b'NEW_MANUAL_WORK')\n            return super().backup(target,*args,**kwargs)\n    def connect(*args,**kwargs):\n        kwargs.setdefault('factory',DuringBackup);return original(*args,**kwargs)\n    sqlite3.connect=connect\n    try:_raises(FileExistsError,recover_latest,[low],raced)\n    finally:sqlite3.connect=original\n    assert raced.read_bytes()==b'NEW_MANUAL_WORK'\nprint('OK')",
